#!/usr/bin/env bash
set -euo pipefail
python -m src.listing_bench.run --config configs/deep_tree.yaml

run: { name: leb-deep }
data: { root: ./data/deep, entries_per_dir: 400, depth: 5 }
benchmark: { concurrency: 8, page_size: 200, warm_cache: false }
output: { dir: metrics }

#!/usr/bin/env bash
set -euo pipefail
python -m src.listing_bench.run --config configs/flat_tree.yaml

#!/usr/bin/env bash
set -euo pipefail
python -m src.io_bench.training --run-name train-small --steps 100 --gbs 128 --mbs 8 --num-workers 4 --mode train

run: { name: leb-flat }
data: { root: ./data/flat, entries_per_dir: 5000, depth: 1 }
benchmark: { concurrency: 16, page_size: 2000, warm_cache: false }
output: { dir: metrics }

#!/usr/bin/env bash
set -euo pipefail
python -m src.io_bench.training --run-name infer-small --steps 200 --gbs 256 --mbs 1 --num-workers 4 --mode infer
